/**
 * i18n: digits, default UI and report strings (fa, en, ar), template filling.
 * Strings are plain templates with {placeholders}; a project overrides any of them in config.strings.
 */
import { DIGIT_SETS, digits as toLocaleDigits, toLatinDigits as latinOf } from "@saasreport/format";

// Digits come from @saasreport/format, the kit's one formatter (docs/CONSTITUTION.md §7).
export const FA_DIGITS = DIGIT_SETS.persian;
export const AR_DIGITS = DIGIT_SETS.arabic;
/** Any digits → Persian digits. */
export const toFaDigits = (v) => toLocaleDigits(v, "fa");
/** Persian / Arabic-Indic digits → ASCII digits. */
export const toLatinDigits = (v) => latinOf(v);

/** Language subtag of a BCP-47 locale or of a config ("fa-IR" → "fa"). */
export function lang(x) {
  const loc = typeof x === "string" ? x : x?.site?.locale;
  return String(loc || "en").toLowerCase().split(/[-_]/)[0];
}
const RTL = new Set(["fa", "ar", "he", "ur", "ps", "ckb", "yi", "dv"]);
/** Text direction of a locale. */
export const dirFor = (locale) => (RTL.has(lang(locale)) ? "rtl" : "ltr");
/** Digits in the script of the locale (Persian digits for fa, ASCII otherwise). */
export const digits = (x, v) => toLocaleDigits(v, lang(x));

/** Fill "{name}" placeholders; unknown placeholders are left as is. */
export const fill = (template, vars = {}) => String(template ?? "").replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? String(vars[k]) : m));

