/** Default strings per language. */
export const STRINGS = { fa: FA, en: EN, ar: AR };

/** The strings table for a config (or locale): language defaults (English fallback) + config.strings overrides. */
export function strings(config) {
  const l = lang(config);
  return { ...EN, ...(STRINGS[l] || {}), ...(typeof config === "object" ? config?.strings || {} : {}) };
}
/** One string, filled: t(config, "episode", { n: 3 }). */
export const t = (config, key, vars) => fill(strings(config)[key] ?? key, vars);
